UI = '\nif(typeof document!==\'undefined\')(()=>{\n \'use strict\';\n const key=\'legacy-guide-storage-key\';\n let state=Guide.empty(),storageOK=true,toastTimer;\n const $=s=>document.querySelector(s);const $$=s=>Array.from(document.querySelectorAll(s));\n try{const stored=localStorage.getItem(key);if(stored)state=Guide.clean(JSON.parse(stored));localStorage.setItem(key,JSON.stringify(state))}catch(e){storageOK=false}\n function toast(text){$(\'#toast\').textContent=text;$(\'#toast\').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>{$(\'#toast\').hidden=true},3200)}\n function save(){try{localStorage.setItem(key,JSON.stringify(state));storageOK=true}catch(e){storageOK=false}$(\'#storage-note\').textContent=storageOK?\'进度已保存在此浏览器。换位置或换浏览器前请导出。\':\'浏览器未允许保存。本次仍可操作；关闭前请导出进度。\'}\n function renderAdvice(){const box=$(\'#advice\');box.replaceChildren();Guide.advice(state.conditions).forEach(a=>{const p=document.createElement(\'p\');p.textContent=a.text;if(a.hold)p.className=\'hold\';box.appendChild(p)})}\n function render(){\n  document.body.classList.add(\'js\');document.body.classList.toggle(\'guided\',!state.all);\n  $$(\'main section\').forEach(s=>s.classList.toggle(\'selected\',s.id===state.current));\n  $$(\'nav a[data-section]\').forEach(a=>{const active=a.dataset.section===state.current;a.classList.toggle(\'active\',active);if(active)a.setAttribute(\'aria-current\',\'step\');else a.removeAttribute(\'aria-current\');const tick=a.querySelector(\'.tick\');if(tick)tick.textContent=state.done.includes(a.dataset.section)?\'✓\':\'·\'});\n  const current=GUIDE_DATA.sections.find(s=>s.id===state.current);$(\'#current-title\').textContent=current.title;\n  $(\'#reading-mode\').textContent=state.all?\'当前：全文阅读，可使用 Ctrl+F\':\'当前：逐章阅读\';$(\'#view-all\').textContent=state.all?\'切换逐章阅读\':\'展开全文\';\n  const i=Guide.ids.indexOf(state.current);$(\'#previous\').disabled=i===0;$(\'#next\').disabled=i===Guide.ids.length-1;\n  $(\'#next\').textContent=state.current===\'verify-backup\'?\'查看本次完成后的处理\':\'下一章\';\n  $(\'#completed-count\').textContent=state.done.length+\' / 9\';$(\'#progress\').value=state.done.length;\n  $$(\'[data-check]\').forEach(c=>c.checked=state.done.includes(c.dataset.check));\n  Object.keys(state.conditions).forEach(k=>{$(\'[data-condition="\'+k+\'"]\').value=state.conditions[k]});renderAdvice();save();\n }\n function navigate(id,scroll=true){if(!Guide.ids.includes(id))return;state.current=id;render();const target=$(\'#\'+id);if(scroll){if(state.all)target.scrollIntoView({block:\'start\'});else $(\'#reading-bar\').scrollIntoView({block:\'start\'})}}\n function setHash(id){if(location.hash===\'#\'+id)navigate(id);else location.hash=id}\n document.addEventListener(\'click\',event=>{const link=event.target.closest(\'a[data-section]\');if(link){event.preventDefault();setHash(link.dataset.section)}});\n window.addEventListener(\'hashchange\',()=>{const id=location.hash.slice(1);if(Guide.ids.includes(id))navigate(id)});\n $(\'#previous\').addEventListener(\'click\',()=>setHash(Guide.ids[Math.max(0,Guide.ids.indexOf(state.current)-1)]));\n $(\'#next\').addEventListener(\'click\',()=>{const target=Guide.next(state.current);if(state.current===\'verify-backup\')toast(\'本次到第 9 章结束。请保存副本并恢复电脑原有网络。\');if(target)setHash(target)});\n $(\'#view-all\').addEventListener(\'click\',()=>{state.all=!state.all;render();navigate(state.current)});\n $(\'#start-guide\').addEventListener(\'click\',()=>{state.all=false;setHash(\'terms\');render()});\n $$(\'[data-check]\').forEach(c=>c.addEventListener(\'change\',()=>{state.done=state.done.filter(id=>id!==c.dataset.check);if(c.checked)state.done.push(c.dataset.check);render();if(state.done.length===9)toast(\'9 章已勾选。请确认第二份备份已保存，然后恢复电脑原有网络。\')}));\n $$(\'[data-condition]\').forEach(s=>s.addEventListener(\'change\',()=>{state.conditions[s.dataset.condition]=s.value;renderAdvice();save()}));\n $(\'#export-progress\').addEventListener(\'click\',()=>{const data={...state,exportedAt:new Date().toISOString(),guide:\'XG040GMD-20261016\'};const blob=new Blob([JSON.stringify(data,null,2)],{type:\'application/json\'});const url=URL.createObjectURL(blob);const a=document.createElement(\'a\');a.href=url;a.download=\'XG040GMD-操作进度-\'+new Date().toISOString().slice(0,10)+\'.json\';document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);toast(\'已请求保存进度文件；请检查浏览器下载。\')});\n $(\'#import-progress\').addEventListener(\'click\',()=>{$(\'#progress-file\').value=\'\';$(\'#progress-file\').click()});\n $(\'#progress-file\').addEventListener(\'change\',async event=>{const file=event.target.files[0];if(!file)return;try{if(file.size>100000)throw Error(\'文件过大\');const data=JSON.parse(await file.text());if(data.guide!==\'XG040GMD-20261016\'||data.version!==1)throw Error(\'不是本手册的进度文件\');state=Guide.clean(data);render();setHash(state.current);toast(\'已恢复进度。请以设备实际状态为准。\')}catch(e){toast(\'未导入：\'+e.message)}});\n function find(){const q=$(\'#search\').value;const results=Guide.search(q);const box=$(\'#search-results\');box.replaceChildren();$(\'#search-count\').textContent=q.trim()?(\'找到 \'+results.length+\' 个章节，显示前 8 个\'):\'可搜索错误原文，例如 USB_READY、hash mismatch、PON。\';results.slice(0,8).forEach(r=>{const li=document.createElement(\'li\'),a=document.createElement(\'a\'),p=document.createElement(\'p\');a.href=\'#\'+r.id;a.dataset.section=r.id;a.textContent=r.title;p.textContent=r.excerpt;li.append(a,p);box.appendChild(li)})}\n $(\'#search\').addEventListener(\'input\',find);$(\'#search-form\').addEventListener(\'submit\',e=>{e.preventDefault();find()});\n $(\'#fault\').addEventListener(\'change\',()=>{const item=Guide.fault($(\'#fault\').value);const box=$(\'#fault-output\');box.replaceChildren();if(!item)return;item.lines.forEach((text,i)=>{const p=document.createElement(\'p\');p.textContent=text;if(i===1)p.className=\'stop\';box.appendChild(p)});const a=document.createElement(\'a\');a.href=\'#\'+item.section;a.dataset.section=item.section;a.textContent=\'查看所在故障章节\';box.appendChild(a)});\n $$(\'.copy\').forEach(button=>button.addEventListener(\'click\',async()=>{const text=button.parentElement.querySelector(\'code\').textContent;let ok=false;try{if(navigator.clipboard&&window.isSecureContext){await navigator.clipboard.writeText(text);ok=true}}catch(e){}if(!ok){const area=document.createElement(\'textarea\');area.value=text;area.style.position=\'fixed\';area.style.left=\'-9999px\';document.body.appendChild(area);area.select();try{ok=document.execCommand(\'copy\')}catch(e){}area.remove()}button.textContent=ok?\'已复制\':\'请手动选中复制\';setTimeout(()=>{button.textContent=\'复制\'},2500)}));\n $(\'#print-guide\').addEventListener(\'click\',()=>window.print());\n const hash=location.hash.slice(1);if(Guide.ids.includes(hash))state.current=hash;render();\n})();\n'

def flattened(blocks):
    lines = []
    for kind, value in blocks:
        if kind in ('p', 'lead', 'h'):
            lines.append(value)
        elif kind in ('steps', 'bullets'):
            lines.extend(value)
        elif kind == 'code':
            lines.extend([value['title'], value['text']])
        elif kind == 'table':
            lines.extend(' '.join(row) for row in value['rows'])
    return ' '.join(lines)
